import json
from pathlib import Path

PATH = Path('ledger.json')

def load(path=PATH):
    if not path.exists():
        return {}
    accounts = json.loads(path.read_text())
    for entry in accounts.values():
        if 'balance' in entry:
            entry['balance_cents'] = round(entry.pop('balance') * 100)
    return accounts

def save(accounts, path=PATH):
    path.write_text(json.dumps(accounts, indent=2))

def deposit(name, cents, path=PATH):
    accounts = load(path)
    entry = accounts.setdefault(name, {'balance_cents': 0})
    entry['balance_cents'] += cents
    save(accounts, path)
    return entry['balance_cents']
